import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Sawmill","description":"","frontmatter":{"title":"Sawmill"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/sawmill.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/sawmill.md"}'),s={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/sawmill.md"};function n(l,e,i,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="sawmill" tabindex="-1">Sawmill <a class="header-anchor" href="#sawmill" aria-label="Permalink to &quot;Sawmill&quot;">​</a></h1><p>The Sawmill is a production building that converts <strong>logs into planks</strong>. Planks can then be sold at forestry selling locations or the central one-stop sell point.</p><p>The Sawmill is part of the Forestry and Logistics progression and requires the <strong>Sawmill License</strong> to use.</p><h2 id="factory-information" tabindex="-1">Factory Information <a class="header-anchor" href="#factory-information" aria-label="Permalink to &quot;Factory Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>Not currently confirmed</td></tr><tr><td>Main Input</td><td>Logs</td></tr><tr><td>Product</td><td>Planks</td></tr><tr><td>Required License</td><td>Sawmill License</td></tr><tr><td>Build Menu</td><td>Create &gt; Buildings</td></tr><tr><td>Selling Location</td><td>WoodNStuff / One-Stop Sell Point</td></tr></tbody></table><p>The Sawmill converts forestry logs into higher-value planks.</p><h2 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h2><p>The Sawmill uses <strong>logs</strong> as its input.</p><table tabindex="0"><thead><tr><th>Material</th><th>Details</th></tr></thead><tbody><tr><td>Pine Logs</td><td>Cannot currently be processed into planks</td></tr><tr><td>Cocoa Logs</td><td>Can be processed into planks</td></tr><tr><td>Cypress Logs</td><td>Can be processed into planks</td></tr><tr><td>Birch Logs</td><td>Can be processed into planks</td></tr></tbody></table><p>According to the available tree documentation, <strong>Cypress and Birch logs</strong> can be turned into planks, while the newer 2026 guide also states that Cocoa harvests can produce logs that can be processed.</p><blockquote><p><strong>Note:</strong> The exact log-to-plank conversion amount can vary depending on the log type.</p></blockquote><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>A fixed processing time for the Sawmill is not currently documented reliably.</p><p>The Sawmill is operated as a processing building: logs are loaded into the input area and planks are collected from the output area.</p><blockquote><p><strong>Note:</strong> The exact processing time should be confirmed in-game before adding a fixed value to the wiki.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>The Sawmill produces <strong>Planks</strong>.</p><table tabindex="0"><thead><tr><th>Product</th><th>Details</th></tr></thead><tbody><tr><td>Planks</td><td>Produced from forestry logs</td></tr><tr><td>Selling Location</td><td>WoodNStuff / One-Stop Sell Point</td></tr></tbody></table><p>Planks generally provide a higher-value alternative to selling the corresponding raw logs. For example, current community data lists Birch Planks at approximately <strong>14,000 Coins per plank</strong> at the rainbow value, compared with 10,080 for a Birch Log.</p><h2 id="selling-price" tabindex="-1">Selling Price <a class="header-anchor" href="#selling-price" aria-label="Permalink to &quot;Selling Price&quot;">​</a></h2><p>Plank prices depend on the type of wood used.</p><table tabindex="0"><thead><tr><th>Wood Type</th><th>Approx. Plank Value</th></tr></thead><tbody><tr><td>Cypress</td><td>9,750 Coins*</td></tr><tr><td>Birch</td><td>14,000 Coins*</td></tr></tbody></table><p>*These are the documented <strong>Rainbow values</strong>, not necessarily the normal selling price.</p><blockquote><p><strong>Note:</strong> Selling prices can change with game updates. Always use the in-game sell value as the final source when recording current prices.</p></blockquote><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>To operate the Sawmill efficiently, you will need:</p><ul><li><strong>Sawmill</strong></li><li><strong>Sawmill License</strong></li><li><strong>Forestry License</strong></li><li><strong>Forestry equipment</strong></li><li><strong>Tree seeds</strong></li><li><strong>Forest Soil</strong></li><li><strong>Log Trailer</strong></li><li><strong>Suitable vehicle for transporting logs</strong></li><li><strong>Suitable vehicle/trailer for transporting planks</strong></li></ul><p>The equipment required depends on the type and scale of forestry operation. Pine trees can be harvested using a Chainsaw, while larger trees such as Cypress and Birch require heavier forestry equipment.</p><h2 id="how-to-use-the-sawmill" tabindex="-1">How to Use the Sawmill <a class="header-anchor" href="#how-to-use-the-sawmill" aria-label="Permalink to &quot;How to Use the Sawmill&quot;">​</a></h2><h3 id="_1-unlock-the-sawmill-license" tabindex="-1">1. Unlock the Sawmill License <a class="header-anchor" href="#_1-unlock-the-sawmill-license" aria-label="Permalink to &quot;1. Unlock the Sawmill License&quot;">​</a></h3><p>The Sawmill License is unlocked through the <strong>Goals progression</strong>.</p><p>The current 2026 progression guide places the Sawmill branch around <strong>14,400 XP</strong>, with linked tasks involving Cocoa harvesting, Chocolate Milk production and forestry/log processing.</p><h3 id="_2-grow-trees" tabindex="-1">2. Grow Trees <a class="header-anchor" href="#_2-grow-trees" aria-label="Permalink to &quot;2. Grow Trees&quot;">​</a></h3><p>Plant suitable trees on <strong>Forest Soil</strong>.</p><p>Cypress and Birch are particularly useful for the Sawmill because their logs can be processed into planks.</p><h3 id="_3-harvest-the-trees" tabindex="-1">3. Harvest the Trees <a class="header-anchor" href="#_3-harvest-the-trees" aria-label="Permalink to &quot;3. Harvest the Trees&quot;">​</a></h3><p>Once the trees are fully grown, use the appropriate forestry equipment to cut them down and collect the logs.</p><p>For example:</p><ul><li><strong>Pine</strong> — Chainsaw</li><li><strong>Cypress</strong> — Tree Cutter</li><li><strong>Birch</strong> — Tree Cutter</li></ul><p>The required equipment depends on the tree type and your Forestry licenses.</p><h3 id="_4-transport-the-logs" tabindex="-1">4. Transport the Logs <a class="header-anchor" href="#_4-transport-the-logs" aria-label="Permalink to &quot;4. Transport the Logs&quot;">​</a></h3><p>Load your logs into an appropriate <strong>Log Trailer</strong> and transport them to your Sawmill.</p><p>Wood trailers are recommended for moving larger quantities of logs.</p><h3 id="_5-load-the-sawmill" tabindex="-1">5. Load the Sawmill <a class="header-anchor" href="#_5-load-the-sawmill" aria-label="Permalink to &quot;5. Load the Sawmill&quot;">​</a></h3><p>Place the logs into the Sawmill&#39;s input area.</p><p>Follow the on-screen prompts to deposit the logs into the factory.</p><h3 id="_6-start-production" tabindex="-1">6. Start Production <a class="header-anchor" href="#_6-start-production" aria-label="Permalink to &quot;6. Start Production&quot;">​</a></h3><p>Start the Sawmill&#39;s production process.</p><p>The logs are processed into <strong>Planks</strong>.</p><h3 id="_7-collect-the-planks" tabindex="-1">7. Collect the Planks <a class="header-anchor" href="#_7-collect-the-planks" aria-label="Permalink to &quot;7. Collect the Planks&quot;">​</a></h3><p>Once processing is complete, collect the finished Planks from the Sawmill&#39;s output area.</p><h3 id="_8-sell-the-planks" tabindex="-1">8. Sell the Planks <a class="header-anchor" href="#_8-sell-the-planks" aria-label="Permalink to &quot;8. Sell the Planks&quot;">​</a></h3><p>Transport the finished Planks to:</p><ul><li><strong>WoodNStuff</strong></li><li><strong>One-Stop Sell Point</strong></li></ul><p>Planks can be sold for more than the corresponding raw-log value, making the Sawmill useful when you already have an established forestry operation.</p><h2 id="sawmill-production-chain" tabindex="-1">Sawmill Production Chain <a class="header-anchor" href="#sawmill-production-chain" aria-label="Permalink to &quot;Sawmill Production Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Forest Soil</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>   Trees</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Harvest / Cut</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>    Logs</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>  Sawmill</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>   Planks</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>WoodNStuff / One-Stop Sell Point</span></span></code></pre></div><h2 id="recommended-trees" tabindex="-1">Recommended Trees <a class="header-anchor" href="#recommended-trees" aria-label="Permalink to &quot;Recommended Trees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tree</th><th>Seed Cost</th><th>Growth Time</th><th>Sawmill</th></tr></thead><tbody><tr><td>Pine</td><td>600 Coins</td><td>12 Minutes</td><td>Not currently documented as usable</td></tr><tr><td>Cocoa</td><td>70,000 Coins</td><td>32 Minutes</td><td>Can produce logs for processing</td></tr><tr><td>Cypress</td><td>150,000 Coins</td><td>38 Minutes</td><td>Yes</td></tr><tr><td>Birch</td><td>210,000 Coins</td><td>55 Minutes</td><td>Yes</td></tr></tbody></table><p>The current tree data lists Pine at 12 minutes, Cocoa at 32 minutes, Cypress at 38 minutes and Birch at 55 minutes without growth multipliers.</p><blockquote><p><strong>Tip:</strong> The Sawmill works particularly well alongside Cocoa forestry because the same forestry operation can contribute toward Chocolate Milk production while providing logs for additional Sawmill income.</p></blockquote>`,61)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
